INSERT INTO TB_TRMA_AREA_BASE_API (
    HUB_TATS_CD
    ,HUB_TATS_NM
    ,HUB_CTGRY_LCLS_NM
    ,HUB_CTGRY_MCLS_NM
    ,AREA_CD
    ,AREA_NM
    ,SIGNGU_CD
    ,SIGNGU_NM
    ,BASE_YM
    ,MAP_X
    ,MAP_Y
    ,HUB_RANK
    ,CREATE_USER
    ,CREATE_DT
    ,UPDATE_USER
    ,UPDATE_DT
    )
    VALUES (
    #{hubTatsCd}
    ,#{hubTatsNm}
    ,#{hubCtgryLclsNm}
    ,#{hubCtgryMclsNm}
    ,#{areaCd}
    ,#{areaNm}
    ,#{signguCd}
    ,#{signguNm}
    ,#{baseYm}
    ,#{mapX}
    ,#{mapY}
    ,#{hubRank}
    ,'batch'
    ,CURRENT_TIMESTAMP
    ,'batch'
    ,CURRENT_TIMESTAMP
)
ON DUPLICATE KEY UPDATE
    HUB_TATS_NM         = #{hubTatsNm}
    ,HUB_CTGRY_LCLS_NM   = #{hubCtgryLclsNm}
    ,HUB_CTGRY_MCLS_NM   = #{hubCtgryMclsNm}
    ,AREA_CD             = #{areaCd}
    ,AREA_NM             = #{areaNm}
    ,SIGNGU_CD           = #{signguCd}
    ,SIGNGU_NM           = #{signguNm}
    ,BASE_YM             = #{baseYm}
    ,MAP_X               = #{mapX}
    ,MAP_Y               = #{mapY}
    ,HUB_RANK            = #{hubRank}
    ,UPDATE_USER         = 'batch'
    ,UPDATE_DT           = CURRENT_TIMESTAMP
;

INSERT INTO TB_TRMA_AREA_BASE_API (
    CONTENTID
    ,MODIFIEDTIME
    ,TITLE
    ,CONTENTTYPEID
    ,LCLS_SYSTM1
    ,LCLS_SYSTM2
