    ,FIRSTIMAGE2
    ,ZIPCODE
    ,ADDR1
    ,ADDR2
    ,MAP_X
    ,MAP_Y
    ,CREATE_USER
    ,CREATE_DT
    ,UPDATE_USER
    ,UPDATE_DT
)VALUES (
    #{contentid}
    ,#{modifiedtime}
    ,#{title}
    ,#{contenttypeid}
    ,#{lclsSystm1}
    ,#{lclsSystm2}
    ,#{lclsSystm3}
    ,#{lDongRegnCd}
    ,#{lDongSignguCd}
    ,#{firstimage}
    ,#{firstimage2}
    ,#{zipcode}
    ,#{addr1}
    ,#{addr2}
    ,#{mapx}
    ,#{mapy}
    ,'batch'
    ,CURRENT_TIMESTAMP
    ,'batch'
    ,CURRENT_TIMESTAMP
)
ON DUPLICATE KEY UPDATE
    MODIFIEDTIME      = VALUES(MODIFIEDTIME)
    ,TITLE             = VALUES(TITLE)
