    ,LCLS_SYSTM1       = VALUES(LCLS_SYSTM1)
    ,LCLS_SYSTM2       = VALUES(LCLS_SYSTM2)
    ,LCLS_SYSTM3       = VALUES(LCLS_SYSTM3)
